   173→		 * inlined. So the loop was unwinded! byte b = readByte(); long i = b & 0x7F; for (int shift = 7; (b & 0x80) != 0; shift
   174→		 * += 7) { b = readByte(); i |= (b & 0x7FL) << shift; } return i;
