   187→		if (b >= 0) { return i; }
   188→		b = readByte();
   189→		i |= (b & 0x7FL) << 28;
   190→		if (b >= 0) { return i; }
   191→		b = readByte();
   192→		i |= (b & 0x7FL) << 35;
   193→		if (b >= 0) { return i; }
   194→		b = readByte();
   195→		i |= (b & 0x7FL) << 42;
   196→		if (b >= 0) { return i; }
