   130→	}
   131→
   132→	public final void writeVInt(int i) throws IOException {
   133→		while ((i & ~0x7F) != 0) {
   134→			writeByte((byte) ((i & 0x7F) | 0x80));
   135→			i >>>= 7;
   136→		}
   137→		writeByte((byte) i);
   138→	}
