   140→	/**
   141→	 * Writes a long as eight bytes.
   142→	 * <p>
   143→	 * 64-bit unsigned integer written as eight bytes, high-order bytes first.
   144→	 * 
   145→	 * @see IndexInput#readLong()
   146→	 */
   147→	public void writeLong(long i) throws IOException {
   148→		writeInt((int) (i >> 32));
   149→		writeInt((int) i);
   150→	}
   151→
   152→	/**
   153→	 * Writes an long in a variable-length format. Writes between one and nine bytes. Smaller values take fewer bytes. Negative
   154→	 * numbers are not supported.
   155→	 * <p>
   156→	 * The format is described further in {@link IndexOutput#writeVInt(int)}.
   157→	 * 
   158→	 * @see IndexInput#readVLong()
   159→	 */
   160→	public final void writeVLong(long i) throws IOException {
   161→		assert i >= 0L;
   162→		while ((i & ~0x7FL) != 0L) {
   163→			writeByte((byte) ((i & 0x7FL) | 0x80L));
   164→			i >>>= 7;
   165→		}
   166→		writeByte((byte) i);
