   347→		if (length == 0) { return; }
   348→		int newLength = length;
   349→		if (v.length > 0) {
   350→			if (start >= v.length) {
   351→				throw new IOException("start position exceeds array length. start=" + start + ", array.length=" + v.length);
   352→			}
   353→			if (start + length > v.length) {
   354→				newLength = v.length - start;
   355→			}
   356→			for (int i = 0; i < newLength; i++) {
