   358→			}
   359→		} else {
   360→			// 기록된바 없음.
   361→			newLength = 0;
   362→		}
   363→		// 나머지 0으로 기록. length와 newLength 가 동일하다면 수행되지 않음.
   364→		for (int i = 0; i < length - newLength; i++) {
