   373→		}
   374→	}
   375→
   376→	/**
   377→	 * Writes a string array, for nullable string, writes it as 0 (empty string).
   378→	 */
   379→	public void writeStringArrayNullable(String[] array) throws IOException {
   380→		if (array == null) {
   381→			writeVInt(0);
   382→		} else {
   383→			writeVInt(array.length);
